sys_script_include.script:
var MediaReviewFilterUtil = Class.create();
MediaReviewFilterUtil.prototype = {
    initialize: function() {},
    refQualMedias: function() {
        var moviesToBeShown = [];
        var grMedias  = new GlideRecord("x_1092529_sharkf_0_media");
        grMedias.addQuery("state", "3");
        grMedias.query();

        while(grMedias.next()){
            var grReview = new GlideRecord("x_1092529_sharkf_0_review");
            // grReview.addQuery("opened_by", "me");
            // grReview.addQuery("state", "3");

            grReview.addQuery("opened_by", gs.getUserID());
            grReview.addQuery("media", grMedias.sys_id);
            grReview.addQuery("state", "!=", "4");
            grReview.query();
            if(!grReview.next()){
                moviesToBeShown.push(grMedias.getUniqueValue());
            }
        }
        return moviesToBeShown;
    },

    type: 'MediaReviewFilterUtil'
};
